    var out = [], d = DATA[b.id] || {};
    Object.keys(d).map(Number).sort(function (a, c) { return a - c; }).forEach(function (n) {
      d[n].split('\n').forEach(function (line) {
        var c = line.split('|'); if (c.length < 2 || !c[0]) return;
        var it = { t: c[0], m: c[1], part: n, bk: b.id }; if (c[2]) it.h = c[2]; if (c[3]) { var g = c[3].split(':'); if (g[0]) it.e = g[0]; if (g[1]) it.r = g[1]; } out.push(it);
      });
    });
    b.done = out.length; b.doneMain = out.length;
    var ex = WPS.VBOOKS.filter(function (x) { return x.id === b.id; })[0];
    if (ex) { for (var k in b) ex[k] = b[k]; } else WPS.VBOOKS.push(b);
